// generateProductAgent creates a clean agent file for OVAV Product.
// Zero OVAV Systems context — professional identity only.
func generateProductAgent(filename string, stack ProjectStack) string {
	profile, ok := agentProfiles[filename]
	if !ok {
		profile = agentProfile{
			Name:      strings.TrimSuffix(strings.TrimPrefix(strings.TrimPrefix(strings.TrimPrefix(filename, "lead-"), "area-"), "team-"), ".md"),
			Area:      "General Engineering",
			Expertise: "Software engineering, code review, architecture",
			Color:     "#6b7280",
		}
	}

	bc := "`"
	date := time.Now().UTC().Format("2006-01-02")

	hidden := "true"
	if strings.HasPrefix(filename, "area-") {
		hidden = "false"
	}

	return "---\n" +
		"name: \"" + profile.Name + "\"\n" +
		"mode: primary\n" +
		"hidden: " + hidden + "\n" +
		"color: \"" + profile.Color + "\"\n" +
		"permission:\n" +
		"  edit: \"allow\"\n" +
		"  bash:\n" +
		"    \"*\": \"allow\"\n" +
		"  external_directory:\n" +
		"    \"*\": \"allow\"\n" +
		"---\n" +
		"\n" +
		"# " + profile.Name + " — " + profile.Area + "\n" +
		"\n" +
		"**Area:** " + profile.Area + "\n" +
		"**Expertise:** " + profile.Expertise + "\n" +
		"\n" +
		"---\n" +
		"\n" +
		"## What You Do\n" +
		"\n" +
		"You are a professional AI agent specialized in " + profile.Expertise + ".\n" +
		"You help with software engineering tasks in your domain.\n" +
		"You adapt to the user's project, preferences, and coding style over time.\n" +
		"\n" +
		"## Core Rules\n" +
		"\n" +
		"### Response Quality\n" +
		"- 50-150 words compact\n" +
		"- Icons + tables + visual hierarchy\n" +
		"- Result first, explanation after\n" +
		"\n" +
		"### Git Discipline\n" +
		"- No " + bc + "git add ." + bc + " — stage exact files\n" +
		"- No raw " + bc + "git push" + bc + " — use workflow commands\n" +
		"- No " + bc + "--force" + bc + ", " + bc + "--skip-gates" + bc + "\n" +
		"- Protected branches: main, master, develop, staging, prod, production\n" +
		"\n" +
		"### Security\n" +
		"- No " + bc + "sudo" + bc + " commands\n" +
		"- No " + bc + "pip install" + bc + " or " + bc + "npm install" + bc + " without approval\n" +
		"- No auth token exposure in output\n" +
		"\n" +
		"---\n" +
		"\n" +
		"*OVAV Product — Generated " + date + "*\n"
}

// generateMimocodeConfig creates mimocode.json for the product surface.
// Includes model routing, permissions, and minimal plugin config.
func generateMimocodeConfig(path string) error {
	content := "{" +
		"\n  \"$schema\": \"https://opencode.ai/config.json\"," +
		"\n  \"agent\": {}," +
		"\n  \"compaction\": {" +
		"\n    \"auto\": true," +
		"\n    \"preserve_recent_tokens\": 3000," +
		"\n    \"tail_turns\": 2" +
		"\n  }," +
		"\n  \"default_agent\": \"Platform Engineering\"," +
		"\n  \"instructions\": [" +
		"\n    \"OVAV_IDENTITY.md\"," +
		"\n    \"AGENTS.md\"" +
		"\n  ]," +
		"\n  \"mcp\": {}," +
		"\n  \"model\": \"openai/gpt-5.6-luna\"," +
		"\n  \"small_model\": \"minimax-coding-plan/MiniMax-M3\"," +
		"\n  \"permission\": {" +
		"\n    \"bash\": {" +
		"\n      \"*\": \"allow\"," +
		"\n      \"sudo *\": \"deny\"," +
		"\n      \"rm -rf / *\": \"deny\"," +
		"\n      \"git push --force *\": \"deny\"," +
		"\n      \"git push -f *\": \"deny\"," +
		"\n      \"npm install *\": \"ask\"," +
		"\n      \"pip install *\": \"ask\"" +
		"\n    }," +
		"\n    \"edit\": \"allow\"" +
		"\n  }," +
		"\n  \"plugin\": []," +
		"\n  \"model_routing\": {" +
		"\n    \"description\": \"Smart model distribution — auto-routes by task type\"," +
		"\n    \"default\": \"openai/gpt-5.6-luna\"," +
		"\n    \"fallback\": \"minimax-coding-plan/MiniMax-M3\"" +
		"\n  }," +
		"\n  \"provider\": {" +
		"\n    \"openai\": {" +
		"\n      \"options\": {" +
		"\n        \"timeout\": 300000" +
		"\n      }" +
		"\n    }" +
		"\n  }," +
		"\n  \"username\": \"\"" +
		"\n}\n"

	return os.WriteFile(path, []byte(content), 0644)
}
